      "content": "import { describe, expect, it } from 'bun:test';
import { DomainError } from '@agentic-ddd/core';
import { covers } from '@agentic-ddd/testing';
import { CreateTask } from '../application/create-task';
import { TaskCreated } from '../domain/task.events';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';

describe('create_task use-case', () => {
  it(covers(['usecase:create_task', 'criterion:0001/persistencia-criacao'], 'salva pending, publica TaskCreated, retorna pending e rejeita duplicado com TASK_ALREADY_EXISTS'), async () => {
    const tasks = new InMemoryTaskRepository();
    const published: unknown[] = [];
    const useCase = new CreateTask(tasks);
    const ctx = { correlationId: 'c1', causationId: 'c1', publish: async (events: readonly unknown[]) => { published.push(...events); } };

    const output = await useCase.execute({ task_id: 't1', title: '  tarefa  ' }, ctx);
    expect(output).toEqual({ task_id: 't1', title: 'tarefa', status: 'pending' });
    const saved = await tasks.findById('t1');
    expect(saved?.status).toBe('pending');
    expect(saved?.title).toBe('tarefa');
    expect(published).toHaveLength(1);
    expect(published[0]).toBeInstanceOf(TaskCreated);
    expect((published[0] as TaskCreated).payload).toEqual({ taskId: 't1', title: 'tarefa' });

    try {
      await useCase.execute({ task_id: 't1', title: 'outra' }, ctx);
      throw new Error('expected DomainError');
    } catch (error) {
      expect(error).toBeInstanceOf(DomainError);
      expect((error as DomainError).code).toBe('TASK_ALREADY_EXISTS');
    }
  });
});
